const DISPLAY_DURATION=8000;const ANIMATION_DELAY=150;const ANIMATION_DURATION=700;document.addEventListener('DOMContentLoaded',function(){const messages=document.querySelectorAll('.message-alert');messages.forEach((message,index)=>{setTimeout(()=>{message.classList.remove('opacity-0','translate-x-full');message.classList.add('animate-entrance');},index*ANIMATION_DELAY);const totalDuration=DISPLAY_DURATION+(index*ANIMATION_DELAY);const progressBar=document.createElement('div');progressBar.className='absolute bottom-0 left-0 h-1 bg-white/30 transform scale-x-0 origin-left';progressBar.style.transition=`transform ${totalDuration}ms linear`;message.appendChild(progressBar);setTimeout(()=>{progressBar.style.transform='scaleX(1)';},50);setTimeout(()=>{dismissMessage(message);},totalDuration);});});function dismissMessage(element){element.classList.add('animate-exit');element.style.transform='translateX(100%) scale(0.95)';element.style.opacity='0';setTimeout(()=>{if(element&&element.parentNode){element.remove();}},ANIMATION_DURATION);};